export const zPeopleSearchCountResponse = z.object({
    output: z.object({
        totalProfilesFound: z.int().gte(0)
    }),
    chargeInfo: z.union([
        z.object({
            method: z.enum(['charged-now']),
            creditsCharged: z.number(),
            lowCreditAlert: z.optional(z.union([
                z.object({
                    getMoreCreditsUrl: z.url(),
                    message: z.string(),
                    availableCredits: z.number()
                }),
                z.null()
            ]))
        }),
        z.object({
            method: z.enum(['charging-later']),
            message: z.string(),
            lowCreditAlert: z.optional(z.union([
                z.object({
                    getMoreCreditsUrl: z.url(),
                    message: z.string(),
                    availableCredits: z.number()
                }),
                z.null()
            ]))
        }),
        z.object({
            method: z.enum(['charged-for-async-process']),
            creditsCharged: z.number(),
            message: z.string(),
            lowCreditAlert: z.optional(z.union([
                z.object({
                    getMoreCreditsUrl: z.url(),
                    message: z.string(),
                    availableCredits: z.number()
                }),
                z.null()
            ]))
        }),
        z.object({
            method: z.enum(['free']),
            message: z.string(),
            lowCreditAlert: z.optional(z.union([
                z.object({
                    getMoreCreditsUrl: z.url(),
                    message: z.string(),
                    availableCredits: z.number()
                }),
                z.null()
            ]))
        })
    ]),
    warnings: z.optional(z.union([
        z.array(z.object({
            field: z.string(),
            message: z.string()
        })),
        z.null()
    ]))
});

